// Autocomplete: ignore stale (out-of-order) responses using a stamp.
let latest = 0;                       // stamp of the newest search
const shown = [];
function search(query, delayMs) {
  const stamp = ++latest;             // every search gets a bigger stamp
  return new Promise(resolve => {
    setTimeout(() => {
      // pretend this is the server reply
      if (stamp !== latest) {         // a newer search exists: drop this reply
        console.log('ignored stale reply for "' + query + '"');
      } else {
        shown.push(query);
        console.log('applied reply for "' + query + '"');
      }
      resolve();
    }, delayMs);
  });
}
async function main() {
  console.log('typing "ja" then "jav"; the first reply is slower');
  const a = search('ja', 60);         // slow reply
  const b = search('jav', 10);        // fast reply, arrives first
  await Promise.all([a, b]);
  console.log('list on screen is for:', shown.join(','));
}
main();

// Offset vs cursor pagination when a new item is inserted at the top.
let feed = [];
for (let i = 10; i >= 1; i--) feed.push({ id: i });   // newest first: 10..1
const offsetPage = (skip, n) => feed.slice(skip, skip + n).map(x => x.id);
// cursor: items strictly older than the last id seen (index-seek in a real DB)
const cursorPage = (after, n) =>
  feed.filter(x => after === null || x.id < after).slice(0, n).map(x => x.id);

const o1 = offsetPage(0, 4);
const c1 = cursorPage(null, 4);
console.log('page 1 (offset):', o1.join(' '));
console.log('page 1 (cursor):', c1.join(' '));
