console.log('page 2 (cursor):', c2.join(' '), '<- no repeat');

// Virtualization: which rows must exist in the DOM?
const rowHeight = 40, viewport = 400, total = 100000, overscan = 3;
function windowFor(scrollTop) {
  const first = Math.max(0, Math.floor(scrollTop / rowHeight) - overscan);
  const last = Math.min(total - 1,
    Math.ceil((scrollTop + viewport) / rowHeight) + overscan);
  return { first, last, count: last - first + 1 };
}
// The spacer keeps the scrollbar the size of the full list.
console.log('spacer height:', total * rowHeight, 'px for', total, 'rows');
for (const top of [0, 1234, 3999960]) {
  const w = windowFor(top);
  console.log('scrollTop', top, '-> render rows', w.first, 'to', w.last,
    '(' + w.count + ' rows)');
}
// Cost depends on window size (about 16 rows), not on 100000.

// Optimistic like button with snapshot rollback.
let state = { liked: false, count: 5 };
const render = label => console.log(label.padEnd(22), JSON.stringify(state));
function fakeServer(ok) {
  return new Promise((res, rej) => setTimeout(() => ok ? res() : rej(new Error('500')), 10));
}
async function like(serverWorks) {
  const snapshot = state;                    // save exactly what to restore
  state = { liked: true, count: state.count + 1 };   // change UI now
  render('optimistic:');
  try {
    await fakeServer(serverWorks);
    render('server confirmed:');
  } catch (e) {
    state = snapshot;                        // failure: restore the snapshot
    render('rolled back (' + e.message + '):');
  }
}
async function main() {
  render('start:');
  await like(true);
  state = { liked: false, count: 5 };
  await like(false);
}
main();

// In-order delivery: hold gaps, drop duplicates, using sequence numbers.
let lastSeq = 0;
const held = new Map();
const shown = [];
function receive(seq) {
  if (seq <= lastSeq) { console.log('drop duplicate', seq); return; }
  held.set(seq, true);                       // buffer it
  while (held.has(lastSeq + 1)) {            // release everything that now fits
    lastSeq++;
    held.delete(lastSeq);
    shown.push(lastSeq);
  }
  console.log('got', seq, '-> shown', shown.join(','),
    '| waiting', [...held.keys()].join(',') || '-');
}
console.log('arrival order: 1 3 2 2 5 4');
[1, 3, 2, 2, 5, 4].forEach(receive);
console.log('final:', shown.join(','));

// Unread count = lastSeq - lastReadSeq (two numbers per conversation).
const conv = { lastSeq: 0, lastReadSeq: 0 };
const unread = c => c.lastSeq - c.lastReadSeq;
const badge = n => (n > 99 ? '99+' : String(n));
function onMessage(seq) { conv.lastSeq = Math.max(conv.lastSeq, seq); }
function markRead(upToSeq) {       // called when newest message is visible + focused
  conv.lastReadSeq = Math.max(conv.lastReadSeq, upToSeq);  // never goes backwards
}
for (let s = 1; s <= 120; s++) onMessage(s);
console.log('after 120 messages: unread', unread(conv), 'badge', badge(unread(conv)));
markRead(100);
console.log('read up to 100: unread', unread(conv), 'badge', badge(unread(conv)));
markRead(50);                      // stale receipt from another device
console.log('late receipt 50: unread', unread(conv));
markRead(120);
console.log('read up to 120: unread', unread(conv));

// Reconnect delays: exponential back-off, cap, jitter.
function delay(attempt, rand) {
  const base = 1000, cap = 30000;
  const exp = Math.min(cap, base * 2 ** attempt);   // 1s,2s,4s,... capped
  return Math.round(exp * (0.5 + 0.5 * rand));      // 50% to 100% of it
}
// fixed "random" numbers so the output is repeatable
const rands = [0.0, 1.0, 0.5, 0.25, 0.75, 1.0, 0.5, 0.5];
console.log('attempt  max-delay  with-jitter');
rands.forEach((r, i) => {
  const max = Math.min(30000, 1000 * 2 ** i);
  console.log(String(i).padEnd(8), String(max).padEnd(10), delay(i, r));
});
console.log('after a stable connection the attempt counter resets to 0');

// Spreadsheet recalculation: dirty set + Kahn topological order.
const formulas = { A1: [], B1: ['A1'], C1: ['A1', 'B1'], D1: ['C1'], X1: ['Y1'], Y1: ['X1'] };
const values = { A1: 5 };
const ops = { B1: v => v.A1 * 2, C1: v => v.A1 + v.B1, D1: v => v.C1 + 1 };
const dependents = {};
for (const c in formulas) for (const p of formulas[c]) (dependents[p] = dependents[p] || []).push(c);
function recalc(edited) {
  const dirty = new Set([edited]);                 // walk dependents
  const stack = [edited];
  while (stack.length) for (const d of dependents[stack.pop()] || [])
    if (!dirty.has(d)) { dirty.add(d); stack.push(d); }
  const indeg = {};                                // in-degree inside dirty set only
  for (const c of dirty) indeg[c] = formulas[c].filter(p => dirty.has(p)).length;
  const queue = [...dirty].filter(c => indeg[c] === 0), order = [];
  while (queue.length) {
    const c = queue.shift(); order.push(c);
    if (ops[c]) values[c] = ops[c](values);
    for (const d of dependents[c] || []) if (--indeg[d] === 0) queue.push(d);
  }
  for (const c of dirty) if (!order.includes(c)) values[c] = '#CYCLE!';
  console.log('edited', edited, '-> order', order.join(' '));
}
values.A1 = 5; recalc('A1');
console.log(JSON.stringify(values));
values.A1 = 10; recalc('A1');
console.log(JSON.stringify(values));
values.X1 = 1; recalc('X1');
console.log('X1 =', values.X1, ', Y1 =', values.Y1);

// Large grid: prefix sums of column widths + binary search for first visible column.
const widths = [80, 120, 60, 200, 100, 90, 150, 70];
const offsets = [0];                         // offsets[i] = left edge of column i
for (const w of widths) offsets.push(offsets[offsets.length - 1] + w);
function firstVisible(scrollLeft) {          // largest i with offsets[i] <= scrollLeft
  let lo = 0, hi = widths.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (offsets[mid] <= scrollLeft) lo = mid; else hi = mid - 1;
  }
  return lo;
}
console.log('offsets:', offsets.join(' '));
for (const x of [0, 79, 80, 300, 500, 869]) {
  console.log('scrollLeft', String(x).padEnd(4), '-> first visible column', firstVisible(x));
}
widths[1] = 220;                             // resize: recompute offsets from column 1 on
for (let i = 1; i < widths.length; i++) offsets[i + 1] = offsets[i] + widths[i];
console.log('after resize:', offsets.join(' '));
// Lookup is O(log columns); rebuilding after a resize is O(columns).

// Kanban: a pure moveCard function is the truth; drag events just call it.
const board = { todo: ['a', 'b', 'c'], doing: ['d'], done: [] };
function moveCard(b, id, from, to, index) {
  const next = {};
  for (const k in b) next[k] = b[k].filter(x => x !== id);   // copy, remove card
  next[to] = next[to].slice();
  next[to].splice(index, 0, id);                              // insert at index
  return next;
}
